<?php
$title='Suscripción';require __DIR__.'/partials/top.php';$owner=isPlatformOwner();$canRequest=!$owner&&in_array($_SESSION['user']['role']??'', ['owner','admin'],true);$plans=[];$tenants=[];$catalog=[];$requests=[];$myPending=[];$currentPlanId=(int)($zynkoPlanContext['plan_id']??0);
try{
 $plans=appDb()->query('SELECT * FROM subscription_plans ORDER BY is_default_free DESC,active DESC,monthly_price,name')->fetchAll();
 $catalog=appDb()->query('SELECT code,name,icon_class FROM channel_connector_catalog WHERE visible=1 ORDER BY sort_order,name')->fetchAll();
 if($owner){
  $tenants=appDb()->query("SELECT t.id,t.name,t.status,ts.plan_id,ts.status subscription_status,sp.name plan_name FROM tenants t LEFT JOIN tenant_subscriptions ts ON ts.tenant_id=t.id LEFT JOIN subscription_plans sp ON sp.id=ts.plan_id ORDER BY t.name")->fetchAll();
  $requests=appDb()->query("SELECT r.id,r.tenant_id,r.plan_id,r.note,r.created_at,t.name company_name,sp.name plan_name,sp.monthly_price,sp.currency,u.name requester_name,u.email requester_email FROM plan_upgrade_requests r JOIN tenants t ON t.id=r.tenant_id JOIN subscription_plans sp ON sp.id=r.plan_id JOIN users u ON u.id=r.requested_by WHERE r.status='pending' ORDER BY r.created_at ASC")->fetchAll();
 }else{
  $q=appDb()->prepare("SELECT plan_id FROM plan_upgrade_requests WHERE tenant_id=? AND status='pending'");$q->execute([(int)$_SESSION['user']['tenant_id']]);$myPending=array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN));
 }
}catch(Throwable $e){}
